INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7595973, 1225712, 87808, '<td valign="top">LOL, it made me chuckle , well done! Vote later, so you don''t know my sneaky score! =P</td>', 'LOL, it made me chuckle , well done! Vote later, so you don''t know my sneaky score! =P', '2018-09-12 01:07:41.000000', NULL, 1),
(7595975, 1225984, 87808, '<td valign="top">Oh just a little more light, to bring out those husk of golden colour, the obvious home made bread, and flour topping it, a little more brightness. teh rustic bread board, oh I wish the grain and brown highlights and low lights came out.  This is such a good picture, but needs boosting in PS. Even tilting the sliced bread at a left angle would help. So delicious though, I can imagine taking this into the garden under a willow tree and slathering on homemade butter churned that morning. Very French, not Italian as it is too wide, this deserves grapes, not olives. Vote later</td>', 'Oh just a little more light, to bring out those husk of golden colour, the obvious home made bread, and flour topping it, a little more brightness. teh rustic bread board, oh I wish the grain and brown highlights and low lights came out.  This is such a good picture, but needs boosting in PS. Even tilting the sliced bread at a left angle would help. So delicious though, I can imagine taking this into the garden under a willow tree and slathering on homemade butter churned that morning. Very French, not Italian as it is too wide, this deserves grapes, not olives. Vote later', '2018-09-12 01:11:43.000000', NULL, 1),
(7595977, 1225844, 87808, '<td valign="top">SO nearly there in my eyes, you have a grain bread, a baguette, a more rustic baguette and a loaf of hopefully white bread.  Perfect positioning on that brown table cloth, but it is boring.   Solid black background, that could have worked.   You have a loaves of bread in a basket that has no charm on a brown table cloth.  Imagine, in your mind, this exact setting, then out a golden side dish of curled butter, some weeping Camembert and the stark contrast of a triangle of blue cheese, giving you the colour, maybe some grapes or vibrant strawberry jam. Imagine yourself in a French countryside, surrounded by weeping willows and a blue tranquil stream. Adding a boost of golden colour to the leavers on the table cloth, or boosting up the contrast or structor on the wicker basket. Bring out the grain in the loaves and basket in colour contrast. I am picturing myself in France right now.  And isnt that what is supposed to be about.  Having a picture that takes you places, out of your mundane life. Vote later for this,</td>', 'SO nearly there in my eyes, you have a grain bread, a baguette, a more rustic baguette and a loaf of hopefully white bread.  Perfect positioning on that brown table cloth, but it is boring.   Solid black background, that could have worked.   You have a loaves of bread in a basket that has no charm on a brown table cloth.  Imagine, in your mind, this exact setting, then out a golden side dish of curled butter, some weeping Camembert and the stark contrast of a triangle of blue cheese, giving you the colour, maybe some grapes or vibrant strawberry jam. Imagine yourself in a French countryside, surrounded by weeping willows and a blue tranquil stream. Adding a boost of golden colour to the leavers on the table cloth, or boosting up the contrast or structor on the wicker basket. Bring out the grain in the loaves and basket in colour contrast. I am picturing myself in France right now.  And isnt that what is supposed to be about.  Having a picture that takes you places, out of your mundane life. Vote later for this,', '2018-09-12 01:18:57.000000', NULL, 1),
(7595978, 1225994, 87808, '<td valign="top">I get where you are coming from. This is so going to bomb though. I am so sorry.  Great take on the challenge though , and I appreciate it!</td>', 'I get where you are coming from. This is so going to bomb though. I am so sorry.  Great take on the challenge though , and I appreciate it!', '2018-09-12 01:20:18.000000', NULL, 1),
